def compile_plan(profile, fabric):
    cal = para.calibrate(profile)
    if cal['status'] != 'ok':
        return {'status': 'inconsistent', 'cycle': cal['cycle']}
    res = solve_fabric(profile, cal, fabric)
    return {'status': 'ok', 'profile': cal, 'period_rounds': res['period'],
            'peaks_as': res['peaks'], 'guard_ns': res['guard'],
            'bounds_as': res['bounds'], 'age_rounds': res['ages'],
            'pred': res['pred'], 'warmup_cycle': res['warmup']}


# ------------------------------------------------------------------ audit
def _is_int(x):
    return type(x) is int


def _check_cycle(cyc, profile):
    if not isinstance(cyc, list):
        return False
    K = int(profile['groups'])
    if len(cyc) < 1 or len(cyc) > K:
        return False
    src, dst, w = para.constraint_arrays(profile['measurements'])
    sl = src.tolist(); dl = dst.tolist(); wl = w.tolist()
    M2 = len(sl)
    prev = None
    total = 0
    for c in cyc:
        if not _is_int(c) or c < 0 or c >= M2:
            return False
        if prev is not None and sl[c] != prev:
            return False
        prev = dl[c]
        total += wl[c]
    if prev is None or sl[cyc[0]] != prev:
        return False
    return total < 0


def _check_cal_artifact(art, profile):
    if not isinstance(art, dict) or art.get('status') != 'ok':
        return False
    if set(art.keys()) != {'status', 'upper_ps', 'pred'}:
        return False
    K = int(profile['groups'])
    meas = profile['measurements']
    up = art['upper_ps']
    pr = art['pred']
    if not isinstance(up, list) or len(up) != K:
        return False
    if not isinstance(pr, list) or len(pr) != K:
        return False
    for row in up:
        if not isinstance(row, list) or len(row) != K:
            return False
        for x in row:
            if not _is_int(x) or x > 10 ** 30 or x < -10 ** 30:
                return False
    for prow in pr:
        if not isinstance(prow, list) or len(prow) != K:
            return False
        for x in prow:
            if x is not None and not _is_int(x):
                return False
    for a in range(K):
        if up[a][a] != 0 or pr[a][a] is not None:
            return False
    for a in range(K):
        row = up[a]
        for x, y, low, high in meas:
            d = row[y] - row[x]
            if d < low or d > high:
                return False
    src, dst, w = para.constraint_arrays(meas)
    sl = src.tolist(); dl = dst.tolist(); wl = w.tolist()
    M2 = len(sl)
    for a in range(K):
        prow = pr[a]
        row = up[a]
        acc = [None] * K
        acc[a] = 0
        for b in range(K):
            if b == a:
                continue
            stack = []
            cur = b
            while True:
                if cur == a or acc[cur] is not None:
                    total = acc[cur]
                    break
                c = prow[cur]
                if not _is_int(c) or c < 0 or c >= M2 or dl[c] != cur:
                    return False
                stack.append((cur, c))
                cur = sl[c]
                if len(stack) > K:
                    return False
            while stack:
                node, c = stack.pop()
                total += wl[c]
                acc[node] = total
            if acc[b] != row[b]:
                return False
    return True


def _flat_matrix(mat, P, N):
    """Flatten a P x N artifact matrix; returns None on a shape defect."""
    if not isinstance(mat, list) or len(mat) != P:
        return None
